
const root=document.getElementById('areiaamigos-view');
if(root){
const materials=['Areia Fina Branca','Areia Fina Amarelinha','Areia Média','Aterro','Areia'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const br=n=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
let records=[],photo='',active='recebimento',selected=null;
const today=()=>new Date().toLocaleDateString('en-CA');
const upload=()=>document.getElementById('aa-file').click();
root.innerHTML='<div class="aa-head"><div><h2>Areia Amigos</h2><p>Controle de recebimento de cargas</p></div><button id="aa-new">＋ Novo recebimento</button></div><div class="aa-tabs"><button data-aa-tab="recebimento" class="active">Recebimento</button><button data-aa-tab="historico">Histórico</button><button data-aa-tab="relatorios">Relatórios</button></div><div id="aa-body"></div><input type="file" id="aa-file" accept="image/jpeg,image/png,image/webp" hidden>';
const fields=()=>['receipt','date','time','client','plate','total',...materials.map((_,i)=>'qty'+i)];
const defaults=()=>({receipt:'',date:today(),time:new Date().toTimeString().slice(0,5),client:'',plate:'',total:'',quantities:[0,0,0,0,0]});
let draft=defaults();
function setTab(tab){active=tab;root.querySelectorAll('[data-aa-tab]').forEach(b=>b.classList.toggle('active',b.dataset.aaTab===tab));draw();}
function collect(){const form=root.querySelector('#aa-form');if(!form)return;const d=new FormData(form);draft={receipt:d.get('receipt')||'',date:d.get('date')||'',time:d.get('time')||'',client:d.get('client')||'',plate:d.get('plate')||'',total:d.get('total')||'',quantities:materials.map((_,i)=>d.get('qty'+i)||'')};}
function input(name,label,type='text',value=''){return '<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(name==='receipt'||name==='date'?'required':'')+'></label>';}
function receiptPanel(){const img=photo?'<img class="aa-receipt-img" src="'+photo+'" alt="Imagem do recibo anexado">':'<div class="aa-drop" id="aa-drop">☁<strong>Arraste a imagem do recibo aqui</strong><small>ou clique para selecionar JPG, PNG ou WEBP</small></div>';return '<div class="aa-columns"><section class="aa-card"><h3>1. Imagem do recibo</h3><div class="aa-image-box">'+img+'</div><div class="aa-actions"><button id="aa-upload">📎 '+(photo?'Trocar imagem':'Selecionar imagem')+'</button><button id="aa-zoom" '+(!photo?'disabled':'')+'>Ampliar</button><button id="aa-remove" '+(!photo?'disabled':'')+'>Remover</button></div></section><section class="aa-card"><h3>2. Informações extraídas da imagem</h3><div class="aa-info" id="aa-info">Anexe um recibo e use “Extrair dados”. Confira as informações antes de salvar.</div><div class="aa-actions"><button id="aa-extract" '+(!photo?'disabled':'')+'>↻ Extrair dados (OCR)</button></div><form id="aa-form"><div class="aa-fields">'+input('receipt','Nº do recibo','text',draft.receipt)+input('date','Data','date',draft.date)+input('time','Hora','time',draft.time)+'</div>'+input('client','Cliente','text',draft.client)+input('plate','Placa','text',draft.plate)+'<h4>Itens da carga (m³)</h4><div class="aa-items">'+materials.map((m,i)=>input('qty'+i,m,'number',draft.quantities[i])).join('')+'</div>'+input('total','Valor total (R$)','text',draft.total)+'<div class="aa-actions aa-right"><button type="button" id="aa-clear">Limpar</button><button class="aa-primary" type="submit">▣ Salvar recebimento</button></div></form></section><section class="aa-card"><h3>3. Pré-visualização</h3><div class="aa-preview">'+(photo?'<img src="'+photo+'" alt="Prévia do recibo">':'Nenhuma imagem anexada')+'</div><h4>Detalhes do recebimento</h4><div class="aa-details" id="aa-details"></div></section></div>';}
function history(){return '<section class="aa-card"><h3>Histórico de recebimentos</h3><div class="aa-filters"><input id="aa-search" placeholder="Buscar cliente, placa ou recibo"><select id="aa-material"><option value="">Todos os materiais</option>'+materials.map(m=>'<option>'+esc(m)+'</option>').join('')+'</select><input id="aa-from" type="date" aria-label="Data inicial"><input id="aa-to" type="date" aria-label="Data final"><button id="aa-export">Exportar CSV</button></div><div class="table-scroll"><table class="aa-table"><thead><tr><th>Data</th><th>Hora</th><th>Recibo</th><th>Cliente</th><th>Placa</th>'+materials.map(m=>'<th>'+m+'</th>').join('')+'<th>Total (R$)</th><th>Imagem</th></tr></thead><tbody id="aa-rows"></tbody></table></div></section>';}
function draw(){const body=root.querySelector('#aa-body');body.innerHTML=(active==='recebimento'?receiptPanel():active==='historico'?history():'<section class="aa-card"><h3>Relatórios de recebimento</h3><div id="aa-summary"></div></section>')+(active==='recebimento'?history():'');if(active==='recebimento'){root.querySelector('#aa-upload').onclick=upload;root.querySelector('#aa-drop')?.addEventListener('click',upload);root.querySelector('#aa-remove').onclick=()=>{photo='';draw()};root.querySelector('#aa-zoom').onclick=()=>{const w=window.open('');if(w)w.document.write('<img src="'+photo+'" style="max-width:100%;height:auto">')};root.querySelector('#aa-clear').onclick=()=>{draft=defaults();photo='';selected=null;draw()};root.querySelector('#aa-extract').onclick=extract;root.querySelector('#aa-form').onsubmit=save;root.querySelector('#aa-form').oninput=()=>{collect();details()};details()}if(active==='relatorios'){root.querySelector('#aa-summary').innerHTML='<p>Total de recebimentos: <strong>'+records.length+'</strong></p><p>Volume recebido: <strong>'+br(records.reduce((a,r)=>a+(r.quantities||[]).reduce((x,y)=>x+Number(y||0),0),0))+' m³</strong></p><p>Valor total: <strong>R$ '+br(records.reduce((a,r)=>a+Number(r.total||0),0))+'</strong></p>'+materials.map((m,i)=>'<p>'+m+': <strong>'+br(records.reduce((a,r)=>a+Number(r.quantities?.[i]||0),0))+' m³</strong></p>').join('')}renderRows();}
function details(){const el=root.querySelector('#aa-details');if(el)el.innerHTML='<p>Recibo: <strong>'+esc(draft.receipt||'—')+'</strong></p><p>Data: '+esc(draft.date||'—')+' · '+esc(draft.time||'—')+'</p><p>Cliente: '+esc(draft.client||'—')+'</p><p>Placa: '+esc(draft.plate||'—')+'</p><p>Valor: R$ '+esc(draft.total||'0,00')+'</p>';}
function renderRows(){const tbody=root.querySelector('#aa-rows');if(!tbody)return;const q=(root.querySelector('#aa-search')?.value||'').toLowerCase(),mat=root.querySelector('#aa-material')?.value||'',from=root.querySelector('#aa-from')?.value||'',to=root.querySelector('#aa-to')?.value||'';const list=records.filter(r=>(!q||[r.receipt,r.client,r.plate].some(v=>String(v||'').toLowerCase().includes(q)))&&(!mat||Number(r.quantities?.[materials.indexOf(mat)]||0)>0)&&(!from||r.date>=from)&&(!to||r.date<=to));tbody.innerHTML=list.map(r=>'<tr><td>'+esc(r.date?.split('-').reverse().join('/'))+'</td><td>'+esc(r.time)+'</td><td>'+esc(r.receipt)+'</td><td>'+esc(r.client)+'</td><td>'+esc(r.plate)+'</td>'+(r.quantities||[]).map(n=>'<td>'+(Number(n)?esc(n):'—')+'</td>').join('')+'<td>'+br(r.total)+'</td><td><button data-aa-open="'+esc(r.id)+'">🖼️ Ver</button></td></tr>').join('')||'<tr><td colspan="11">Nenhum recebimento encontrado.</td></tr>';tbody.querySelectorAll('[data-aa-open]').forEach(b=>b.onclick=()=>{const r=records.find(x=>x.id===b.dataset.aaOpen);if(!r)return;selected=r.id;draft={...r};photo=r.image||'';setTab('recebimento')});}
async function load(){try{const r=await fetch('/api/areia-amigos');if(!r.ok)throw Error('Falha ao carregar');records=(await r.json()).records||[];draw()}catch(e){root.querySelector('#aa-body').innerHTML='<p>Erro ao carregar recebimentos: '+esc(e.message)+'</p>'}}
async function save(e){e.preventDefault();collect();if(!photo)return alert('Anexe a imagem do recibo antes de salvar.');const amount=String(draft.total).replace(/\./g,'').replace(',','.');const entry={...draft,id:selected||crypto.randomUUID(),total:Number(amount)||0,quantities:draft.quantities.map(x=>Number(x)||0),image:photo};try{const r=await fetch('/api/areia-amigos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)});const j=await r.json();if(!r.ok)throw Error(j.error||'Não foi possível salvar');records=j.records;draft=defaults();photo='';selected=null;setTab('historico');alert('Recebimento salvo com imagem!')}catch(err){alert(err.message)}}
function fileToData(file){return new Promise((resolve,reject)=>{if(file.size>5*1024*1024)return reject(Error('Imagem acima de 5 MB. Reduza a foto.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
root.querySelector('#aa-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{collect();photo=await fileToData(file);draw()}catch(err){alert(err.message)}e.target.value=''};
root.querySelectorAll('[data-aa-tab]').forEach(b=>b.onclick=()=>{collect();setTab(b.dataset.aaTab)});root.querySelector('#aa-new').onclick=()=>{draft=defaults();photo='';selected=null;setTab('recebimento')};
root.addEventListener('input',e=>{if(['aa-search','aa-material','aa-from','aa-to'].includes(e.target.id))renderRows()});
root.addEventListener('click',e=>{if(e.target.id!=='aa-export')return;const head=['Data','Hora','Recibo','Cliente','Placa',...materials,'Total'];const lines=records.map(r=>[r.date,r.time,r.receipt,r.client,r.plate,...r.quantities,r.total]);const csv=[head,...lines].map(a=>a.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='areia-amigos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
async function extract(){
const info=root.querySelector('#aa-info');info.textContent='Lendo regiões do recibo (número, cliente, placa, data, hora, materiais e total)...';
try{
 if(!window.Tesseract){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Biblioteca OCR indisponível.'));document.head.appendChild(s)})}
 const img=new Image();img.src=photo;await img.decode();
 const regions={receipt:[.65,.17,.34,.12],client:[.12,.23,.61,.09],plate:[.03,.33,.37,.07],date:[.39,.33,.29,.07],time:[.68,.33,.31,.07],items:[.02,.38,.54,.32],total:[.60,.72,.39,.13]};
 const crop=([x,y,w,h])=>{const canvas=document.createElement('canvas');const scale=3;canvas.width=Math.round(img.naturalWidth*w*scale);canvas.height=Math.round(img.naturalHeight*h*scale);const ctx=canvas.getContext('2d');ctx.filter='grayscale(1) contrast(1.65)';ctx.drawImage(img,img.naturalWidth*x,img.naturalHeight*y,img.naturalWidth*w,img.naturalHeight*h,0,0,canvas.width,canvas.height);return canvas};
 const out={};for(const [key,rect] of Object.entries(regions)){info.textContent='Lendo '+({receipt:'número',client:'cliente',plate:'placa',date:'data',time:'hora',items:'materiais',total:'valor'}[key])+'...';try{out[key]=(await Tesseract.recognize(crop(rect),'por',{logger:()=>{}})).data.text.trim()}catch{out[key]=''}}
 const n=out.receipt.match(/\b(\d{4,6})\b/);if(n)draft.receipt=n[1];
 const date=out.date.match(/(\d{1,2})\s*[\/.|\-]\s*(\d{1,2})\s*[\/.|\-]\s*(20\d{2}|\d{2})/);if(date){const year=date[3].length===2?'20'+date[3]:date[3];const day=Number(date[1]),month=Number(date[2]);if(day>=1&&day<=31&&month>=1&&month<=12)draft.date=year+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0')}
 const time=out.time.match(/\b([01]?\d|2[0-3])\s*[:h.]\s*([0-5]\d)\b/);if(time)draft.time=time[1].padStart(2,'0')+':'+time[2];
 const plate=out.plate.toUpperCase().replace(/[^A-Z0-9]/g,'').match(/[A-Z]{3}[0-9][A-Z0-9][0-9]{2}/);if(plate)draft.plate=plate[0];
 const client=out.client.replace(/^(?:cliente|cllente)\s*[:.]?/i,'').replace(/[^A-Za-zÀ-ÿ\s]/g,' ').replace(/\s+/g,' ').trim();if(client.length>=4&&client.length<=55&&!/^(cliente|cnpj|cidade)$/i.test(client))draft.client=client;
 const amount=out.total.match(/(\d{1,5})\s*[,\.]\s*(\d{2})/);if(amount)draft.total=amount[1]+','+amount[2];
 // A tabela tem cinco linhas fixas. Só atribuir quantidade quando houver número isolado à esquerda da linha correspondente.
 const rows=out.items.split(/\n/).filter(Boolean);for(const line of rows){const m=line.match(/^\s*(\d{1,3})(?:\s*m[³3])?\s+(areia\s*fina\s*branca|areia\s*fina\s*amarelinha|areia\s*m[eé]dia|aterro|areia)\b/i);if(!m)continue;const label=m[2].toLowerCase();const index=label.includes('branca')?0:label.includes('amarelinha')?1:label.includes('média')||label.includes('media')?2:label.includes('aterro')?3:4;draft.quantities[index]=Number(m[1])}
 draw();root.querySelector('#aa-info').textContent='Leitura por regiões concluída. Confira especialmente os campos manuscritos e as quantidades; campos não reconhecidos foram preservados para correção manual.';
}catch(err){info.textContent='Não foi possível concluir o OCR: '+err.message+'. Preencha manualmente.'}
}
load();
}
